        }
    }

    // 3. Fragmentation Control: Avoid creating very small residuals (e.g., 1-9) which are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // 4. Harmonic Scaling: Favor bins that align with the mean density of current open bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. New Bin Thresholding: 
    // If we are forced to open a new bin (bin_residual == bin_capacity), 
    // only do so if the current fitting options are extremely poor (high score).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high to encourage filling existing ones.
        score = 40.0; 

        // If we have many open bins that fit poorly, allow opening a new one.
        if open_bins_count > 5 {
            score -= 10.0;
        }
    }

    // 6. Last Chance Logic: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 7. Progression factor: Be more conservative with bin space as the stream nears the end.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
