    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Penalize new bin creation (bin_residual == bin_capacity) using a dynamic threshold
    // based on stream progression to encourage tighter packing as the stream nears completion.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (25.0 + (progress * 50.0)) * (1.0 + (fitting_bins_count as f64).sqrt())
    } else {
        0.0
    };

    // Best-Fit Decreasing logic with a non-linear penalty for small gaps.
    // Gaps that are too small to fit future items (using next_item_size as a heuristic guide)
