    let gap_penalty = if post < (next_item_size as f64) && post > 0.0 {
        (1.0 / (post + 0.1)) * 10.0
    } else {
        post * 0.5
    };

    // Favor bins that align with the global mean residual to keep bin states uniform.
    let uniformity_bonus = (post - mean_residual).abs() * 0.2;

    // Interaction term: If this is the last fitting bin, prioritize it to avoid opening a new one,
    // unless the fit is extremely poor (post_residual < 5).
