        0.0
    };

    let mut score = gap_penalty + uniformity_bonus + new_bin_penalty + desperation_factor;

    // Apply a slight curvature to the score to prefer larger fills as the stream progresses.
    score += (1.0 - progress) * (bin_capacity as f64 - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
